import numpy as np, math

class Body:
 def __init__(self,x,w,h):
  self.p=np.array([float(x),h/2]); self.v=np.zeros(2);self.a=0.;self.om=0.;self.w=w;self.h=h;self.I=(w*w+h*h)/12
 def vertices(self):
  c,s=np.cos(self.a),np.sin(self.a)
  return np.array([[-self.w/2,-self.h/2],[self.w/2,-self.h/2],[self.w/2,self.h/2],[-self.w/2,self.h/2]])@np.array([[c,s],[-s,c]])+self.p

def cross(a,b):return a[0]*b[1]-a[1]*b[0]
def vel(b,r):return b.v+b.om*np.array([-r[1],r[0]])
def contact(a,b):
 A=a.vertices(); B=b.vertices();best=1e9;n=None
 for ang in [a.a,b.a]:
  for ax in [np.array([math.cos(ang),math.sin(ang)]),np.array([-math.sin(ang),math.cos(ang)])]:
   ap=A@ax;bp=B@ax; ov=min(ap.max(),bp.max())-max(ap.min(),bp.min())
   if ov<=0:return []
   if ov<best:best=ov;n=ax if np.dot(b.p-a.p,ax)>0 else -ax
 # clipped polygon of intersection
 pts=list(A.copy())
 for i in range(4):
  out=[]; p=B[i];q=B[(i+1)%4]; edge=q-p
  for j in range(len(pts)):
   S=pts[j-1];E=pts[j];ds=cross(edge,S-p);de=cross(edge,E-p)
   if de>=0:
    if ds<0:out.append(S+(E-S)*ds/(ds-de))
    out.append(E)
   elif ds>=0:out.append(S+(E-S)*ds/(ds-de))
  pts=out
  if not pts:return []
 pts=np.array(pts); tangent=np.array([-n[1],n[0]]); plane=(np.max(A@n)+np.min(B@n))/2
 lo=np.min(pts@tangent);hi=np.max(pts@tangent)
 pp=[n*plane+tangent*lo]
 if hi-lo>2:pp.append(n*plane+tangent*hi)
 return [(a,b,p,n,best,0.,0.) for p in pp]

def simulate(nframes=120):
 bs=[Body(x,w,h) for x,w,h in zip([125,182,231,285,325,362],[24,24,24,22,22,24],[112,108,104,106,102,101])]
 dt=1/240; result=[]
 for step in range(nframes*10):
  if step==170: bs[-1].v[0]=-42; bs[-1].om=2.35
  for b in bs:
   b.v[1]-=500*dt;b.p+=b.v*dt;b.a+=b.om*dt
  contacts=[]
  for b in bs:
   for p in b.vertices():
    if p[1]<.2:contacts.append([None,b,p,np.array([0.,1.]),max(0.,-p[1]),0.,0.])
  for i in range(6):
   for j in range(i+1,6): contacts.extend([list(x) for x in contact(bs[i],bs[j])])
  for _ in range(12):
   for cc in contacts:
    a,b,p,n,depth,jn,jt=cc;ra=p-a.p if a else np.zeros(2);rb=p-b.p
    vn=np.dot(vel(b,rb)-(vel(a,ra) if a else 0),n)
    denom=1+cross(rb,n)**2/b.I+(1+cross(ra,n)**2/a.I if a else 0)
    target=.16*max(depth-.03,0)/dt
    dj=(target-vn)/denom;new=max(0,jn+dj);dj=new-jn;cc[5]=new
    imp=dj*n;b.v+=imp;b.om+=cross(rb,imp)/b.I
    if a:a.v-=imp;a.om-=cross(ra,imp)/a.I
    t=np.array([-n[1],n[0]]);vt=np.dot(vel(b,rb)-(vel(a,ra) if a else 0),t)
    den=1+cross(rb,t)**2/b.I+(1+cross(ra,t)**2/a.I if a else 0)
    dj=-vt/den;new=np.clip(jt+dj,-.62*cc[5],.62*cc[5]);dj=new-jt;cc[6]=new
    imp=dj*t;b.v+=imp;b.om+=cross(rb,imp)/b.I
    if a:a.v-=imp;a.om-=cross(ra,imp)/a.I
  if step%10==0:result.append([[*b.p,b.a] for b in bs])
 return np.array(result)
if __name__=='__main__':
 r=simulate();np.save('.tmp/states.npy',r)
 for k in [0,17,20,25,30,35,40,45,50,60,75,100,119]:print(k, np.round(np.rad2deg(r[k,:,2]),1),np.round(r[k,:,0],1),np.round(r[k,:,1],1))
